// The homepage's fractal layer: one fixed canvas behind the page, its camera a
// pure function of scroll. At rest on load it is the "o" of the title; the
// moment the page scrolls it leaves the word, growing through the slice's
// four-dimensional stages, holds a view beside each section of text, and at
// the end shrinks into the "o" of the second title, where the letter takes
// its place. stage.js, renderer.js, shaders.js and path.js came from the
// qjulia renderer (~/Documents/qjulia); homeShots.js is generated by
// scripts/home-shots/make-home.mjs.
import { start } from './stage.js';
import { makePath, toCamera, flat, smooth } from './path.js';
import { SCENE } from './scene.js';
import { HOME_SHOTS, BALL_RADIUS } from './homeShots.js';
import { TITLE_HOLD_VH } from '../homeScroll.js';

const TAN = Math.tan((40 * Math.PI) / 360); // the ball's lens: 40° vertical
const BEAT_VH = 0.8;      // a beat (a view with no words) holds this many viewport heights
const MOVE_MIN_VH = 0.4;  // and the moves around it never get less than this
const VIA_TIME = 0.35;    // extra time a move gets for each via point it passes
const NOTE_ALPHA = 1;     // how strong the notes are at their fullest
// Speed bumps: how long each of three moments must be on screen before the
// scroll may pass it (ms). See bumpCheck.
const BUMPS = { o: 900, face: 1400, land: 800 };

const clamp01 = (n) => Math.min(1, Math.max(0, n));
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const root = document.documentElement;
const canvas = document.getElementById('qj');
const note = document.querySelector('.fx-note');
const docTop = (el) => el.getBoundingClientRect().top + scrollY;

// Where a letter's ink sits on screen: centre and radius, from the font's own
// glyph measurements and a zero-size probe sitting on the baseline, so the
// ball covers the glyph exactly and keeps the letter's own spacing.
// The browser rounds these measurements to whole pixels, so the glyph is
// measured at eight times its size.
function inkOf(span) {
  const cs = getComputedStyle(span);
  const size = parseFloat(cs.fontSize);
  const ctx = document.createElement('canvas').getContext('2d');
  ctx.font = `${cs.fontWeight} ${size * 8}px ${cs.fontFamily}`;
  const big = ctx.measureText(span.textContent);
  const m = {};
  for (const k of ['actualBoundingBoxLeft', 'actualBoundingBoxRight', 'actualBoundingBoxAscent', 'actualBoundingBoxDescent']) m[k] = big[k] / 8;
  const r = span.getBoundingClientRect();
  const probe = document.createElement('span');
  probe.style.cssText = 'display:inline-block;width:0;height:0;vertical-align:baseline';
  span.appendChild(probe);
  const baseline = probe.getBoundingClientRect().top;
  probe.remove();
  return {
    x: r.left + (m.actualBoundingBoxRight - m.actualBoundingBoxLeft) / 2,
    y: baseline + (m.actualBoundingBoxDescent - m.actualBoundingBoxAscent) / 2,
    r: ((m.actualBoundingBoxRight + m.actualBoundingBoxLeft) / 2 + (m.actualBoundingBoxAscent + m.actualBoundingBoxDescent) / 2) / 2,
    size,
    // where the ink centre sits inside the glyph's own box, from its left
    // edge and from its baseline
    inX: (m.actualBoundingBoxRight - m.actualBoundingBoxLeft) / 2,
    inY: (m.actualBoundingBoxDescent - m.actualBoundingBoxAscent) / 2,
    fa: big.fontBoundingBoxAscent / 8, fd: big.fontBoundingBoxDescent / 8,
  };
}

// A solid ball reads heavier than the ring of an "o", and the "a" before it
// is a full-height stem while the "t" after it reaches over only with its
// crossbar: measured row by row, a ball the size of the glyph crowds the "a".
// The ball is smaller and nudged toward the "t", and the letter condenses into
// exactly that footprint as the ball takes its place (the page's .as-ball),
// so the two always coincide. The outer span keeps the layout and is what is
// measured; only the glyph inside it moves, about its own ink centre, which
// is found from the font's metrics and the glyph box's layout height (both
// untouched by the animation).
function letterBall(span) {
  const ink = inkOf(span);
  const glyph = span.querySelector('.title-o-glyph');
  const drop = INK_DROP * ink.size;
  const toBaseline = (glyph.offsetHeight - (ink.fa + ink.fd)) / 2 + ink.fa;
  const dx = BALL_NUDGE * ink.size, r = ink.r * BALL_SIZE;
  const ox = ink.inX, oy = toBaseline + ink.inY + drop;
  span.style.setProperty('--o-origin', `${ox.toFixed(2)}px ${oy.toFixed(2)}px`);
  // The hole closes as the letter condenses: a ring centred on the ink, kept
  // inside the stroke (the "o"'s outer edge never comes nearer its centre than
  // 0.96 of the ink radius, its hole never reaches past 0.57), thickening
  // inward from there until it is a disc.
  span.style.setProperty('--o-ox', `${ox.toFixed(2)}px`);
  span.style.setProperty('--o-oy', `${oy.toFixed(2)}px`);
  span.style.setProperty('--o-fill', `${(ink.r * 0.9).toFixed(2)}px`);
  span.style.setProperty('--o-open', `${(ink.r * 0.32).toFixed(2)}px`);
  span.style.setProperty('--o-dx', `${dx.toFixed(2)}px`);
  span.style.setProperty('--o-scale', ((r + BALL_EDGE) / ink.r).toFixed(4));
  return { x: ink.x + dx, y: ink.y + drop, r };
}

// Hands an "o" to the ball (on) or back to the letter (off), playing the
// page's animation for whichever way it goes: through a solid dot when the
// ball is being shown or hidden at the same moment, so it goes in or out
// underneath the dot; else the ring alone, the ball being on screen already.
function setBall(span, on, viaDot) {
  if (on === span.classList.contains('as-ball')) return;
  span.classList.toggle('as-ball', on);
  span.classList.toggle('out-of-ball', !on);
  span.classList.toggle('via-dot', viaDot);
}

const BALL_SIZE = 0.8;    // of the glyph's ink radius
const BALL_NUDGE = 0.038; // em, toward the next letter
// The rendered glyph sits about 0.75 px lower than its font metrics say (the
// text renderer snaps it to the pixel grid); measured at 1, 1.25, 1.5 and 2x
// density, the error stays within 0.35 px once this is added.
const INK_DROP = 0.0125;  // em
// The ball's rendered edge reaches this far past its nominal radius
// (anti-aliasing), so the condensed letter is sized to meet it exactly.
const BALL_EDGE = 0.75;   // px

// Station values that draw the ball centred on screen point (x, y), radius r px,
// in the canvas's own box (A.vw × A.vh; see measure).
// While the ball is letter-sized its hit threshold is held tight (see
// cam.detail in renderer.js), or it would swell past the letter it replaces.
const BALL_DETAIL = 0.012;
const ballAt = (x, y, r) => flat({
  az: 50, el: 15, target: [0, 0, 0], fov: 40, iter: 18, rot4: [90, 0],
  dist: BALL_RADIUS / ((r / (A.vh / 2)) * TAN),
  offset: [(x - A.vw / 2) / (A.vh / 2), (A.vh / 2 - y) / (A.vh / 2)],
});
// Between two sets of station values; distance in log space so a zoom feels even.
const blend = (a, b, t) => {
  const v = {};
  for (const k in a) v[k] = k === 'dist' ? Math.exp(Math.log(a.dist) + (Math.log(b.dist) - Math.log(a.dist)) * t) : a[k] + (b[k] - a[k]) * t;
  return v;
};

const debug = new URLSearchParams(location.search).has('debug');
const WAKE = 0.005;  // viewport heights of scroll that turn the first "o" into the ball
let shown = false;   // whether the canvas is showing the ball
let A = null;        // anchors, in document px, measured from the page
let journey = null;  // the held shots and the moves between them

function measure() {
  // The frame is the canvas's own box: the window less any classic
  // scrollbar, so page positions and the picture share one coordinate space.
  const vh = canvas.clientHeight, vw = canvas.clientWidth;
  const S = Math.max(1, root.scrollHeight - vh);

  // The first title floats fixed and rises (the choreography script in the
  // page moves it). The ball only needs its "o" where the title starts, at
  // rest on load, half-way down the viewport.
  const header = document.querySelector('.intro-spacer .title-section-parallax');
  const o1 = letterBall(header.querySelector('.title-o'));
  const h = header.getBoundingClientRect();
  const titleStart = (vh - header.offsetHeight) * 0.5;
  // The second title rises from its clip line; measured as if fully risen.
  const title2 = document.querySelector('.return-stage .cards-title .title-main');
  const keep = title2.style.transform;
  title2.style.transform = 'none';
  const o2 = letterBall(title2.querySelector('.title-o'));
  title2.style.transform = keep;
  o2.docY = o2.y + scrollY;

  // Each section's words fade in as they rise to their place, stay while
  // they are stuck there, and fade as they leave. The view holds for all of
  // that, so words never sit over a moving scene. Beside the words is the
  // free space a view centres its subject in.
  const windows = {}, texts = [], spaces = {};
  for (const sec of document.querySelectorAll('.fx-section')) {
    const top = docTop(sec), text = sec.querySelector('.fx-text');
    const stickyTop = parseFloat(getComputedStyle(text).top) || 0;
    const stick = top - stickyTop;
    const unstick = top + sec.offsetHeight - text.offsetHeight - stickyTop;
    const win = { el: text, a: stick - 0.35 * vh, b: stick - 0.1 * vh, c: unstick, d: unstick + 0.2 * vh };
    texts.push(win);
    windows[sec.dataset.text] = win;
    const r = text.getBoundingClientRect(), gutter = 0.03 * vw;
    spaces[sec.dataset.text] = sec.classList.contains('right') ? [gutter, r.left - gutter] : [r.right + gutter, vw - gutter];
  }
  const spacer = docTop(document.querySelector('.return-spacer'));
  A = {
    S, vh, vw,
    o1: { x: o1.x, y: titleStart + (o1.y - h.top), r: o1.r, el: header.querySelector('.title-o') },
    o2: { ...o2, el: title2.querySelector('.title-o') },
    // a nudge of scroll turns the first title's "o" into the ball, while the
    // title holds still; it rises once the hold is over, and once it has
    // cleared the ball the title gets its own "o" back
    wake: WAKE * vh,
    hold: TITLE_HOLD_VH * vh,
    release: (TITLE_HOLD_VH + 0.04) * vh,
    // the second title has fully risen at this scroll (see returnFx in the page)
    land: spacer + 0.8 * vh,
    texts,
  };
  A.ballAt = A.land - 0.75 * vh;

  // A shot as this screen frames it: centred in the space beside its words,
  // and pulled back if that space is too narrow for its shape.
  const place = (shot) => {
    const st = structuredClone(shot.st);
    if (shot.layout) {
      const [x0, x1] = spaces[shot.text];
      st.offset = [((x0 + x1) / 2 - vw / 2) / (vh / 2), (st.offset || [0, 0])[1]];
      if (shot.fit) {
        const tan = Math.tan((st.fov * Math.PI) / 360);
        st.dist = Math.max(st.dist, (shot.fit * vh) / 2 / (tan * 0.42 * (x1 - x0)), shot.fit / (0.82 * tan));
      }
    }
    return st;
  };
  // drift is per viewport of scroll: a longer hold turns further, not faster
  const turned = (drift, px) => Object.fromEntries(Object.entries(drift).map(([k, v]) => [k, (v * px) / vh]));

  // Text shots hold over their section's window; beats share the gap between
  // two sections, each move given time for the via points it passes.
  const placed = HOME_SHOTS.map(place);
  const stations = [];
  HOME_SHOTS.forEach((s, i) => {
    if (s.text) {
      const w = windows[s.text];
      stations.push({ ...placed[i], at: w.a / S, hold: (w.d - w.a) / S, drift: turned(s.drift, w.d - w.a), src: i });
    } else if (s.id === 'ball') stations.push({ ...placed[i], at: A.ballAt / S, hold: 0, src: i });
  });
  const out = [];
  for (let k = 0; k < stations.length; k++) {
    const st = stations[k];
    out.push(st);
    if (k === stations.length - 1) break;
    const next = stations[k + 1];
    const beats = HOME_SHOTS.slice(st.src + 1, next.src).map((b, j) => ({ ...b, src: st.src + 1 + j }));
    const moves = [HOME_SHOTS[st.src], ...beats];
    const weight = moves.map((m) => 1 + VIA_TIME * m.vias.length);
    const from = st.at + st.hold, span = next.at - from;
    let beatHold = (BEAT_VH * vh) / S;
    beatHold = Math.max(0, Math.min(beatHold, (span - (MOVE_MIN_VH * vh * moves.length) / S) / Math.max(1, beats.length)));
    const unit = (span - beatHold * beats.length) / weight.reduce((x, y) => x + y, 0);
    let t = from;
    moves.forEach((m, j) => {
      const len = weight[j] * unit;
      m.vias.forEach((v, q) => out.push({ ...v, at: t + ((q + 1) / (m.vias.length + 1)) * len }));
      t += len;
      if (j < beats.length) {
        const b = beats[j], a0 = t * S, a1 = (t + beatHold) * S, fadeIn = Math.min(0.15 * vh, (a1 - a0) / 3);
        out.push({ ...placed[b.src], at: t, hold: beatHold, drift: turned(b.drift, a1 - a0) });
        windows[b.id] = { a: a0, b: a0 + fadeIn, c: a1 - fadeIn, d: a1 };
        t += beatHold;
      }
    });
  }
  journey = makePath(out.map(({ src, ...st }) => st), { monotone: true });
  A.eggStart = stations[0].at * S;
  A.eggV = flat(placed[0]);
  A.ballV = flat(HOME_SHOTS[HOME_SHOTS.length - 1].st);

  // The notes: a faint arrow from a short caption to the subject of each
  // view, there while the view holds. The subject is the shot's target, which
  // the lens shift puts exactly at the shot's offset on screen.
  A.notes = [];
  note.querySelector('svg').setAttribute('viewBox', `0 0 ${vw} ${vh}`);
  HOME_SHOTS.forEach((s, i) => {
    const li = document.querySelector(`.fx-notes [data-shot="${s.id}"]`);
    const w = s.text ? windows[s.text] : windows[s.id];
    if (!li || !w) return;
    const [ox, oy] = placed[i].offset || [0, 0];
    const tx = vw / 2 + (ox * vh) / 2, ty = vh / 2 - (oy * vh) / 2;
    const cx = clamp(tx + parseFloat(li.dataset.dx) * vh, 0.04 * vw, 0.96 * vw);
    const cy = clamp(ty + parseFloat(li.dataset.dy) * vh, 0.06 * vh, 0.94 * vh);
    A.notes.push({ text: li.textContent.trim(), a: w.a, b: w.b, c: w.c, d: w.d, tx, ty, cx, cy });
  });
  A.noteOn = null;
  A.windows = windows;
  if (debug) window.qjHome = { A, stations: out };
}

// A camera between two station values, its hit threshold eased from tight
// (the letter-sized ball) to normal in log space.
const between = (a, b, t, detailA, detailB) => {
  const cam = toCamera(blend(a, b, t));
  cam.detail = Math.exp(Math.log(detailA) + (Math.log(detailB) - Math.log(detailA)) * t);
  return cam;
};

function camera(p) {
  const y = p * Math.max(1, root.scrollHeight - innerHeight);
  // From the "o" where the title starts, straight out to the first view: the
  // ball does not ride along with the rising title.
  if (y < A.eggStart) return between(ballAt(A.o1.x, A.o1.y, A.o1.r), A.eggV, smooth(clamp01((y - A.hold) / (A.eggStart - A.hold))), BALL_DETAIL, 1);
  if (y <= A.ballAt) return journey(p);
  // Into the second title's "o", which moves up with the page; once there the
  // letter replaces the ball (see syncPage).
  const inO = ballAt(A.o2.x, A.o2.docY - y, A.o2.r);
  return between(A.ballV, inO, smooth(clamp01((y - A.ballAt) / (A.land - A.ballAt))), 1, BALL_DETAIL);
}

// How present something with a fade window is at scroll y.
const presence = (y, w) => (y < w.b ? smooth(clamp01((y - w.a) / (w.b - w.a))) : y <= w.c ? 1 : 1 - smooth(clamp01((y - w.c) / (w.d - w.c))));

// The note's arrow is a short pointer just off its caption, aimed at the
// subject; it never reaches into the shape. The caption sits on the far side
// of the pointer.
function drawNote(n) {
  const dx = n.tx - n.cx, dy = n.ty - n.cy, len = Math.hypot(dx, dy) || 1;
  const ux = dx / len, uy = dy / len;
  const reach = Math.min(clamp(0.055 * A.vh, 36, 60), len * 0.5);
  const sx = n.cx + ux * 6, sy = n.cy + uy * 6, ex = sx + ux * reach, ey = sy + uy * reach;
  const hx = ux * 6, hy = uy * 6;
  const d = `M${sx.toFixed(1)} ${sy.toFixed(1)} L${ex.toFixed(1)} ${ey.toFixed(1)} `
    + `M${(ex - hx - hy * 0.6).toFixed(1)} ${(ey - hy + hx * 0.6).toFixed(1)} L${ex.toFixed(1)} ${ey.toFixed(1)} `
    + `L${(ex - hx + hy * 0.6).toFixed(1)} ${(ey - hy - hx * 0.6).toFixed(1)}`;
  for (const path of note.querySelectorAll('path')) path.setAttribute('d', d);
  const text = note.querySelector('.fx-note-text');
  text.textContent = n.text;
  const toLeft = n.tx < n.cx;
  text.style.left = toLeft ? `${n.cx + 10}px` : 'auto';
  text.style.right = toLeft ? 'auto' : `${A.vw - n.cx + 10}px`;
  text.style.textAlign = toLeft ? 'left' : 'right';
  text.style.top = `${n.cy}px`;
}

// Everything on the page that follows the view, from the same scroll position
// it is drawn at: the words' and the notes' opacity, and the two "o"s. At the
// top, before any scroll, the first title keeps its "o"; a nudge turns it into
// the ball, which the title leaves behind as it rises, getting its "o" back.
// At the end the ball goes into the second title's "o".
function syncPage(p) {
  const y = p * Math.max(1, root.scrollHeight - innerHeight);
  const landed = y >= A.land;
  const show = y > A.wake && !landed, flip = show !== shown;
  shown = show;
  setBall(A.o1.el, show && y <= A.release, flip);
  setBall(A.o2.el, !landed, flip);
  canvas.style.opacity = show ? '' : '0';
  for (const t of A.texts) t.el.style.opacity = presence(y, t).toFixed(3);
  let on = null, most = 0;
  for (const n of A.notes) { const o = presence(y, n); if (o > most) { most = o; on = n; } }
  if (on && on !== A.noteOn) drawNote(on);
  A.noteOn = on;
  note.style.opacity = (most * NOTE_ALPHA).toFixed(3);
}

// Speed bumps. Most visitors fly through a first pass, and three moments only
// work if they are seen: the first title's "o" turning into the ball (a 0.75 s
// animation in the title's still zone), "cut open" (the flat 2d julia set
// inside the solid, with its note), and the ball going into the second
// title's "o". Whoever reaches the end of one sooner than BUMPS allows after
// it came on screen is held there for the rest of that time. Each holds once
// per visit, only going down, and never for a deliberate jump (End, a
// scrollbar drag, a link) of more than a screen and a half at once.
const bumpSeen = {};  // when each moment came on screen, or true once passed
let held = null;      // the bump holding the scroll: { y, until }
let lastY = 0;
const bumpSpans = () => [
  ['o', A.wake, A.hold - 2],
  ['face', A.windows.face.b, A.windows.face.c],
  ['land', A.land, A.land + 2],
];
function stopDown(e) {
  const down = e.type === 'wheel' ? e.deltaY > 0
    : ['ArrowDown', 'PageDown', 'End'].includes(e.key) || (e.key === ' ' && !e.shiftKey);
  if (held && down) e.preventDefault();
}
function release() {
  held = null;
  removeEventListener('wheel', stopDown);
  removeEventListener('keydown', stopDown);
}
function bumpCheck() {
  const y = scrollY, now = performance.now(), jump = Math.abs(y - lastY) > 1.5 * A.vh;
  lastY = y;
  if (held) {
    if (now >= held.until) release();
    else if (y > held.y) scrollTo({ top: held.y, behavior: 'instant' });
    return;
  }
  for (const [name, from, to] of bumpSpans()) {
    if (bumpSeen[name] === true) continue;
    if (jump) { if (y > to) bumpSeen[name] = true; continue; }
    if (y >= from && bumpSeen[name] === undefined) bumpSeen[name] = now;
    if (y > to && bumpSeen[name] !== undefined) {
      const until = bumpSeen[name] + BUMPS[name];
      bumpSeen[name] = true;
      if (now < until) {
        held = { y: Math.round(to), until };
        scrollTo({ top: held.y, behavior: 'instant' });
        addEventListener('wheel', stopDown, { passive: false });
        addEventListener('keydown', stopDown);
        setTimeout(release, until - now);
        return;
      }
    }
  }
}

export async function run() {
  await document.fonts.ready;
  canvas.style.opacity = '0'; // out of sight until syncPage says otherwise
  const stage = await start({ scene: SCENE, path: (p) => camera(p), onFrame: (p) => { if (A) syncPage(p); }, glide: false });
  if (!stage) return; // the page stays as it is: text, no fractal
  // Live: the sections open up into long holds, and the second title's "o"
  // gives way to the ball. Measured after, since the layout has just changed.
  root.classList.add('fx-live');
  measure();
  syncPage(scrollY / Math.max(1, root.scrollHeight - innerHeight));
  lastY = scrollY;
  for (const [name, , to] of bumpSpans()) if (scrollY > to) bumpSeen[name] = true;
  // ?nobumps turns them off, for checking the pacing (and for tools that jump
  // the scroll around, which would otherwise be held like a fast visitor)
  if (!new URLSearchParams(location.search).has('nobumps')) addEventListener('scroll', bumpCheck, { passive: true });
  const relayout = () => {
    const live = !window.qjStats.mode.startsWith('poster');
    root.classList.toggle('fx-live', live);
    if (live) measure();
    else {
      for (const t of A.texts) t.el.style.opacity = '';
      for (const o of [A.o1.el, A.o2.el]) o.classList.remove('as-ball', 'out-of-ball', 'via-dot');
      canvas.style.opacity = '';
      note.style.opacity = '0';
    }
  };
  addEventListener('resize', relayout);
  addEventListener('load', relayout);
  // A GPU that proves too slow hands back to the plain page.
  addEventListener('scroll', () => { if (window.qjStats.mode.startsWith('poster') && root.classList.contains('fx-live')) relayout(); }, { passive: true });
}
